import{z as i,x as n,o as e,c as s,q as l,j as A,D as E,d as r,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"多模态越狱","description":"","frontmatter":{"title":"多模态越狱","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multimodal-jailbreak.md","filePath":"llm/multimodal-jailbreak.md","lastUpdated":1791063341000}'),d={name:"llm/multimodal-jailbreak.md"};function m(p,a,h,u,c,_){const t=n("Mermaid");return e(),s("div",null,[a[2]||(a[2]=l('<h1 id="多模态越狱" tabindex="-1">多模态越狱 <a class="header-anchor" href="#多模态越狱" aria-label="Permalink to &quot;多模态越狱&quot;">​</a></h1><div class="epigraph"><p>视觉通道一旦进入同一条自回归序列，只对文本角色做对齐的护栏就会漏看图里的指令；评测应覆盖跨模态转移，而不是只扫纯文本红队集。</p><footer>—— 对照视觉指令模型把图块投影进语言模型词空间的公开架构，以及后续多模态红队与护栏工作对「图文不一致」的讨论</footer></div><p><a href="/llm/indirect-injection">上一课</a>把载荷放到检索、浏览、邮件等数据通道：防御靠抽取/决策隔离与索引鉴权，不是单靠系统提示。缺口是通道从「返回的文本块」换成图像（有时还有音频）：对齐大多在文本指令上做，很少以视觉 token 为条件。本课写多模态越狱的通道错位。不重讲 RAG 投毒的下线块流程，也不给出图文配方。后课后缀优化默认已经读完：文本护栏看不见 \\(v\\) 时，政策等于没写进损失。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯文本护栏默认用户意图写在 <code>user</code> 角色的字符串里。视觉语言模型（VLM）的用户消息却是「一段字 + 一组图块」。图块经视觉编码器与<a href="/llm/llava-projector">投影器</a>进入语言模型，位置上往往紧挨着一句看起来无害的提问。若安全分类器只吃文本、或只吃「这张图的简短说明」，它看到的是 innocuous 的提问，看不到图里的排版字、示意图、或对抗扰动所改变的视觉表示。对齐过的语言模型对「直接用文字提出的危害请求」会拒绝，对「请描述 / 请按图中步骤说明」这类元指令则更愿意配合——因为后者在文本 SFT 里大量出现，属于有用行为。</p><p>跨模态还带来分布外。文本越狱的梯度与后缀优化假定离散词表；图像是连续像素，扰动可以很小却稳定地改变编码器输出。反过来，把危害字印在图上，走的是 OCR 式读取，而不是文本 tokenizer 的子词切分，<a href="/llm/llama-guard">Llama Guard</a> 一类文本分类器若未先看图，等于没看见那句话。交错训练（见<a href="/llm/interleaved-multimodal">多模态交错</a>）让图和字在上下文里轮流出现，也让「哪一段才是真正的指令」变得可操纵。</p><h3 id="文本护栏看不见的那一段条件" tabindex="-1">文本护栏看不见的那一段条件 <a class="header-anchor" href="#文本护栏看不见的那一段条件" aria-label="Permalink to &quot;文本护栏看不见的那一段条件&quot;">​</a></h3><p>设融合后的条件是 \\(p_\\theta(y \\mid x_{\\mathrm{text}}, v)\\)，其中 \\(v\\) 是视觉 token。拒答策略若近似为「当 \\(x_{\\mathrm{text}}\\) 落在危害集合时降低配合续写的概率」，则 \\(v\\) 可以在 \\(x_{\\mathrm{text}}\\) 保持无害的同时，把隐状态推到文本对齐从未正则过的区域。这不是模型「忘了政策」，而是政策从来没有以 \\(v\\) 为条件写进损失。评测若只换文本红队提示、配一张无关的猫图，会严重低估真实风险。</p><p><span class="marginnote">「看图说话」在有用性数据里是高频技能：模型被训练成要读出图中文字、箭头与步骤。把安全完全寄托在文本侧拒答，等于要求模型在同一技能上按通道切换人格。通道切换没有单独的监督时，技能会赢。</span></p><p><span class="marginnote">直觉类比：安检仪只细查随身的纸条，行李箱走的是免检通道。纸条查得再严，指令写在箱内 T 恤的图案上也查不到。「条件错位」指的正是这种不一致——护栏的检查范围与指令实际进入模型的通道对不上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>讨论方法时分成三类观测，而不是一份攻击菜谱。第一类是<strong>语义落在像素里</strong>：图中含有模型能读的文字或符号，文本侧只给中性任务（描述、转写、按图执行）。防御侧对应的是：必须让图的内容进入与文本同一套安全分类，而不是相信用户字幕。第二类是<strong>连续扰动</strong>：在编码器可微的前提下改像素，使视觉表示靠近某类有害文本所诱导的隐状态。防御侧对应的是预处理（压缩、缩放、重编码）、随机化、以及在表示空间而不是像素空间做检测。第三类是<strong>模态拆台</strong>：文本声称无害、图像另有所指，或多图之间互相引用。防御侧对应的是跨模态一致性检查：图说与字说是否指向同一任务。</p><p>评测协议应固定模型、解码、图像分辨率与预处理，再报告：无图纯文本基线、有图但图与字一致的有害请求、图文不一致、以及经过标准有损变换后的稳健性。指标不要只用「是否拒绝」二值：过拒绝（把无害医疗图、化学实验教学图拒掉）必须单独成列，否则任何「全拒」系统都会在越狱表上看起来很强。</p><p><span class="marginnote">「过拒绝」就是把无害内容也拦下：化学教学图、战争新闻摄影被当成危害请求。它必须单独成列，因为「一律拒绝」的系统在越狱成功率表上很漂亮，可用性上却是灾难——安全分和过拒绝率要成对报，缺一个都无法判断护栏好坏。</span></p>',14)),(e(),A(o,null,{default:E(()=>[B(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20A1%5B%22%E7%B1%BB%E5%9E%8B%E4%B8%80%EF%BC%9A%E8%AF%AD%E4%B9%89%E5%8D%B0%E5%9C%A8%E5%83%8F%E7%B4%A0%E9%87%8C%22%5D%20--%3E%20P1%5B%22OCR%20%E5%BC%8F%E8%AF%BB%E5%8F%96%E5%9B%BE%E5%86%85%E6%96%87%E5%AD%97%E6%88%96%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20A1%20--%3E%20D1%5B%22%E9%98%B2%E5%BE%A1%EF%BC%9A%E5%9B%BE%E5%86%85%E5%AE%B9%E8%BF%9B%E5%90%8C%E4%B8%80%E5%A5%97%E5%AE%89%E5%85%A8%E5%88%86%E7%B1%BB%22%5D%0A%20%20A2%5B%22%E7%B1%BB%E5%9E%8B%E4%BA%8C%EF%BC%9A%E8%BF%9E%E7%BB%AD%E5%83%8F%E7%B4%A0%E6%89%B0%E5%8A%A8%22%5D%20--%3E%20P2%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%E8%A1%A8%E7%A4%BA%E8%A2%AB%E5%B0%8F%E5%B9%85%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E7%A7%BB%22%5D%0A%20%20A2%20--%3E%20D2%5B%22%E9%98%B2%E5%BE%A1%EF%BC%9A%E6%9C%89%E6%8D%9F%E9%A2%84%E5%A4%84%E7%90%86%20%2B%20%E8%A1%A8%E7%A4%BA%E7%A9%BA%E9%97%B4%E6%A3%80%E6%B5%8B%22%5D%0A%20%20A3%5B%22%E7%B1%BB%E5%9E%8B%E4%B8%89%EF%BC%9A%E5%9B%BE%E6%96%87%E4%BA%92%E7%9B%B8%E6%8B%86%E5%8F%B0%22%5D%20--%3E%20P3%5B%22%E5%AD%97%E9%9D%A2%E5%A3%B0%E7%A7%B0%E6%97%A0%E5%AE%B3%E3%80%81%E5%9B%BE%E5%83%8F%E5%8F%A6%E6%9C%89%E6%89%80%E6%8C%87%22%5D%0A%20%20A3%20--%3E%20D3%5B%22%E9%98%B2%E5%BE%A1%EF%BC%9A%E8%B7%A8%E6%A8%A1%E6%80%81%E4%B8%80%E8%87%B4%E6%80%A7%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="先对齐再分类-还是先看图再对齐" tabindex="-1">先对齐再分类，还是先看图再对齐 <a class="header-anchor" href="#先对齐再分类-还是先看图再对齐" aria-label="Permalink to &quot;先对齐再分类，还是先看图再对齐&quot;">​</a></h3><p>工程上常见两条流水线。一条是生成后再用文本安全分类器扫输出，见 <a href="/llm/llama-guard">Llama Guard</a> 与 <a href="/llm/wildguard-harmbench">WildGuard</a>；VLM 的漏洞在于<strong>有害内容可能已在生成中展开</strong>，分类器只能事后截断。另一条是在解码前对 \\((x_{\\mathrm{text}}, v)\\) 做输入分类：需要视觉理解能力，成本接近一次短生成。实践中常两者都要：输入分类挡明显的图内指令，输出分类挡「看起来在描述、实际在给步骤」的续写。Constitutional 式分类器把规则写成自然语言再合成数据，见<a href="/llm/constitutional-classifiers">宪法分类器</a>，对多模态要把「图像中的文字视为用户指令」写进条款，否则合成数据仍是纯文本。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制的核心是条件错位与表示可加性。视觉 token 与文本 token 在残差流里相加或拼接，后续层并不区分来源。若某一层的线性方向同时被「危害文本」和「某种视觉模式」激活，那么只惩罚文本侧的对齐更新，不会自动正交掉视觉侧的同类方向。这与<a href="/llm/repeng-refusal">表示工程</a>看到的现象是同一几何：概念往往有可读取的方向；多模态只是给了第二条写入该方向的路径。</p><p>OCR 通路尤其直白。视觉编码器与后续语言模型对印刷体、屏幕截图、幻灯片有很强的转写能力，因为预训练与指令数据都奖励「把图里的字读对」。图内文字不经过用户侧的敏感词过滤器，也不经过 chat template 里对 <code>user</code> 字符串的正则。排版、分栏、低对比，只影响识别质量，不改变「这是指令」这一事实。对抗扰动则走另一条路：人眼未必能读出指令，编码器输出却能系统性偏移；它更接近连续优化，而不是社会工程。</p><p><span class="marginnote">把截图当用户消息，等于把任意网页与任意聊天记录变成了视觉前缀。服务端若只对上传文件做病毒扫描、不做语义安全分类，护栏的覆盖与纯文本 API 不对称。</span></p><h3 id="防御评测要拆开的三件事" tabindex="-1">防御评测要拆开的三件事 <a class="header-anchor" href="#防御评测要拆开的三件事" aria-label="Permalink to &quot;防御评测要拆开的三件事&quot;">​</a></h3><p>稳健性、过拒绝、转移。稳健性：同一语义在纯文本、图内文字、图文拆台、轻度有损变换下，拒绝率是否掉下来。过拒绝：医学示意图、新闻战争摄影、安全研究论文截图、化学分子式教学图，是否被当成危害。转移：在模型 A 的视觉编码器上有效的扰动或排版，换到模型 B、换分辨率、换<a href="/llm/interleaved-multimodal">交错</a>模板后是否仍有效。只报「某红队集攻击成功率」而不报这三列，无法区分「护栏真的看见图」还是「护栏变得更爱拒绝」。</p><p><span class="marginnote">「转移」一列为什么重要：如果一段扰动只在模型 A 上有效，说明抓到的是该模型的个体弱点；换编码器、换分辨率后仍然有效，才说明触到了共享的表示几何。只测自家模型的红队成绩，很容易把前者误读成「已修复」。</span></p>',9)),(e(),A(o,null,{default:E(()=>[B(t,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E8%A7%86%E8%A7%89%E8%BE%93%E5%85%A5%22%5D%20--%3E%20ENC%5B%22%E8%A7%86%E8%A7%89%E7%BC%96%E7%A0%81%E4%B8%8E%E6%8A%95%E5%BD%B1%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20FUSE%5B%22%E8%9E%8D%E5%90%88%E5%BA%8F%E5%88%97%22%5D%0A%20%20ENC%20--%3E%20FUSE%0A%20%20FUSE%20--%3E%20LM%5B%22%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%E7%94%9F%E6%88%90%22%5D%0A%20%20IMG%20--%3E%20VIN%5B%22%E8%BE%93%E5%85%A5%E4%BE%A7%E5%A4%9A%E6%A8%A1%E6%80%81%E5%88%86%E7%B1%BB%22%5D%0A%20%20TXT%20--%3E%20VIN%0A%20%20VIN%20--%3E%20GATE%7B%22%E6%94%BE%E8%A1%8C%3F%22%7D%0A%20%20GATE%20--%3E%7C%22%E5%90%A6%22%7C%20REF%5B%22%E6%8B%92%E7%BB%9D%E6%88%96%E6%94%B9%E5%86%99%22%5D%0A%20%20GATE%20--%3E%7C%22%E6%98%AF%22%7C%20LM%0A%20%20LM%20--%3E%20VOUT%5B%22%E8%BE%93%E5%87%BA%E4%BE%A7%E5%AE%89%E5%85%A8%E5%88%86%E7%B1%BB%22%5D%0A%20%20VOUT%20--%3E%20Y%5B%22%E5%AF%B9%E7%94%A8%E6%88%B7%E5%8F%AF%E8%A7%81%E7%9A%84%E5%9B%9E%E7%AD%94%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有单一预处理能同时挡住排版字与不可见扰动：强压缩会伤 OCR 与细粒度理解，弱压缩对连续扰动几乎无操作。随机化（多次缩放再投票）能提高检测召回，但延迟与费用随次数线性涨，且对已经印在图上的高对比文字帮助有限。完全依赖输出分类器，则危害步骤可能已经生成了一半才被截断，日志与流式接口仍会泄漏前缀。</p><p>开源 VLM 的安全训练数据公开程度远低于文本对话；把纯文本 Llama Guard 直接套在「先用模型自己给图做一句话描述，再分类」上，描述模型若已被同一张图带偏，分类器吃到的是洗过的摘要。更稳的做法是独立视觉编码器 + 独立分类器，接受它与生成模型的视觉前端不一致，并在评测里显式报告这种不一致带来的漏检。音频、视频只是把 \\(v\\) 变得更长，机制同类：时序里也可以藏指令。本篇不展开其它模态的构造，只强调<strong>凡是能写入残差流的通道，都要进入同一套安全分类与过拒绝评测</strong>。</p><p><span class="marginnote">产品上「支持贴图」是功能，不是安全边界。边界是：图中文字、示意图与扰动，是否被当成与 <code>user</code> 字符串同等的指令来源。没写进政策的通道，等于没对齐。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多模态越狱的要点是条件错位：文本侧无害、视觉侧写入指令或有害方向，只对字符串对齐的护栏会漏看。</li><li>图内文字走 OCR 技能，连续扰动走编码器表示；两类不是同一防御。</li><li>输入分类与输出分类都要，且分类器必须真正看到图像，而不是只看用户字幕。</li><li>评测应同时报稳健性、过拒绝与跨模型/跨预处理转移，避免「全拒」虚高。</li><li>表示空间上，视觉与文本可写入同一线性方向，这与拒绝的表示干预是对偶现象。</li><li>预处理有损变换是辅助，不是策略；流式输出在分类器截断前仍可能泄漏。</li><li>出处：视觉指令架构以 Liu 等 LLaVA 与后续 VLM 为公开参照；跨模态红队与护栏评测见各家多模态安全报告，具体数字以原文表格为准。</li></ul>',6))])}const F=i(d,[["render",m]]);export{C as __pageData,F as default};
